     proof! { assert(crate::mem::PAGE_TABLE_LENGTH == 1024) by (compute); }
     // The mask guarantees the result is always < PAGE_TABLE_LENGTH.
     let index: usize = (vaddr >> crate::mem::PGTAB_SHIFT) & (crate::mem::PAGE_TABLE_LENGTH - 1);
